import {PAPER,CSS_PAPER} from './paper-size.14116c902b79.js';
import {DAYS,CATEGORIES,defaultOffice,validateOffice,consultationWeeks,freshState,buildMonth,monthRecord,validateMonth,validateSessions,validateRelatedActivity,validateBackup,daysInMonth,timeLabel,duration} from './model.14116c902b79.js';
import {generateDocx,renderDocument,makePDF,download} from './documents.14116c902b79.js';
const KEY='dtr-fdtr-generator-v1',main=document.querySelector('main'),dialog=document.querySelector('#dialog');
let state=freshState(),storageIssue='',view='home',type='dtr',step=0,month=new Date().toLocaleDateString('en-CA',{year:'numeric',month:'2-digit'}).slice(0,7),previewBlob=null,restoreCandidate=null,undo=null,changeDraft=null,scheduleIndex=null,toastTimer,previewRequest=0;
if(!/^\d{4}-\d{2}$/.test(month))month=`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`;
try{const saved=localStorage.getItem(KEY);if(saved)state=validateBackup(JSON.parse(saved));}catch{storageIssue='Your saved information could not be opened. Restore a backup in Settings, or enter your information again. The existing save has not been overwritten.';}
let protectSave=!!storageIssue,dialogOpener=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const field=(label,key,value,{max=80,inputType='text',hint='',required=false}={})=>`<div><label for="f-${key.replace('.','-')}">${label}</label><input id="f-${key.replace('.','-')}" data-field="${key}" type="${inputType}" value="${esc(value)}" maxlength="${max}" ${required?'required':''} ${hint?`aria-describedby="hint-${key.replace('.','-')}"`:''}>${hint?`<p class="hint" id="hint-${key.replace('.','-')}">${hint}</p>`:''}</div>`;
function save(){previewBlob=null;if(protectSave){document.querySelector('#save-status').textContent='Save needs attention';return;}try{localStorage.setItem(KEY,JSON.stringify(state));document.querySelector('#save-status').textContent='✓ Saved';storageIssue='';}catch{storageIssue='Your browser could not save your changes. Keep this page open and use Save Backup in Settings.';document.querySelector('#save-status').textContent='Changes not saved';toast(storageIssue);}}
function toast(message,withUndo=false){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.innerHTML=esc(message)+(withUndo?button('Undo','undo'):'')+button('Dismiss','dismiss-toast','quiet','aria-label="Dismiss message"');el.classList.add('visible');if(!withUndo)toastTimer=setTimeout(()=>el.classList.remove('visible'),12000);}
function show(next){view=next;render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function titleMonth(){return new Date(`${month}-01T12:00:00`).toLocaleDateString('en-US',{month:'long',year:'numeric'});}
function header(title,subtitle=''){return `${button('‹ Back',view==='setup'?'back-setup':'home','quiet back')}<div class="heading-row"><div><p class="eyebrow">${type.toUpperCase()} · ${view==='setup'?'Your saved setup':'Monthly form'}</p><h1>${title}</h1><p class="muted">${subtitle}</p></div></div>`;}
function issueBanner(){return storageIssue?`<div class="errors" role="alert">${esc(storageIssue)} ${button('Open Settings','settings')}</div>`:'';}
function render(){previewRequest++;main.innerHTML=issueBanner()+({home:home,setup:setup,month:monthly,settings:settings,preview:preview}[view]||home)();document.title=`${view==='home'?'DTR & FDTR Generator':view==='settings'?'Settings':view==='setup'?`Set up ${type.toUpperCase()} · Step ${step+1}`:view==='preview'?`Preview ${type.toUpperCase()}`:`Create ${type.toUpperCase()}`} · Monthly time records`;if(view==='preview')loadPreview();}
function home(){return `<div class="intro"><p class="eyebrow">Less monthly paperwork</p><h1>Make monthly time records easier.</h1><p class="muted">Save your usual schedule once. Each month, add what changed, check your form, and download it.</p></div><ol class="journey" aria-label="How it works"><li><span>1</span>Choose your form</li><li><span>2</span>Add monthly changes</li><li><span>3</span>Review & download</li></ol><div class="choices">${['dtr','fdtr'].map(t=>`<button class="choice" data-action="choose" data-type="${t}"><span class="doc-label">${t.toUpperCase()}</span><strong>${t==='dtr'?'Daily Time Record':'Faculty Daily Time Record'}</strong><p>${t==='dtr'?'Lecture and laboratory hours.':'Teaching, consultation and other faculty work.'}</p><span class="status">${state.setups[t].ready?'Continue with your saved schedule →':'Start with a guided setup →'}</span></button>`).join('')}</div><div class="privacy-note"><span aria-hidden="true">⌂</span>No account needed. Your information stays in this browser.</div><details class="home-help"><summary>First time here?</summary><p>Choose the form your office requires. We will guide you through your name, usual schedule and signatory. You can change them later in Settings.</p><p>Returning next month? Your schedule is already saved in this browser. In Settings, use Save Backup to keep a copy or move your information to another device.</p></details>`;}
function setup(){const s=state.setups[type],p=state.profile;return `<div class="narrow">${header(`Set up your ${type.toUpperCase()}`,'You normally only need to do this once. You can change it later.')}<ol class="steps">${['Your Information','Your Usual Schedule','Certification / Signatory'].map((x,i)=>`<li ${i===step?'class="current" aria-current="step"':''}>${i+1}. ${x}</li>`).join('')}</ol><form id="setup-form"><section class="panel">${step===0?`<h2>Your information</h2><p class="hint">Your name is shared between the two forms.</p><div class="form-grid">${field('Full name','profile.name',p.name,{required:true,max:36})}${type==='fdtr'?`${field('Department','profile.department',p.department,{required:true,max:32})}${field('Name with qualifications (for signature)','profile.signatureName',p.signatureName,{max:42,hint:'Leave blank to use your full name.'})}${field('Designation','profile.designation',p.designation,{required:true,max:36})}`:''}</div>`:step===1?`<h2>Your usual schedule</h2><p class="hint">${type==='fdtr'?'Add recurring class, consultation and other work. Add order-based Related activities in the monthly form.':'Add recurring periods. The app will work out their dates and hours each month.'}</p><div class="form-grid">${field('Academic term (optional)','setup.term',s.term,{max:60})}${field('Schedule starts (optional)','setup.from',s.from,{inputType:'date'})}${field('Schedule ends (optional)','setup.to',s.to,{inputType:'date'})}</div>${type==='fdtr'&&s.schedule.some(p=>p.category==='related')?'<p class="hint">Your existing setup has recurring Related activities. Remove those periods here if they apply only to particular dates, then enter them as monthly changes.</p>':''}${scheduleList()}${button('Add a time period','add-schedule')}${type==='fdtr'?officeControls():''} ${type==='dtr'?`<details><summary>Official-hours lines on the form</summary><p class="hint">Enter the wording your office requires. Unfilled lines remain blank.</p><div class="form-grid">${field('Official hours for','setup.official',s.official,{max:36})}${field('Regular days','setup.regular',s.regular,{max:42})}${field('Saturdays','setup.saturday',s.saturday,{max:30})}${field('Sundays','setup.sunday',s.sunday,{max:30})}</div></details>`:''}`:`<h2>Certification / signatory</h2><p class="muted">The certification wording and signature positions come from your institutional form.</p>${field(type==='dtr'?'In-charge name':'Head of department / unit','setup.signatory',s.signatory,{required:true,max:type==='dtr'?30:40})}<p class="hint">Include a title such as “ATTY.” only if it belongs on this form.</p>`}<div id="setup-error" role="alert"></div></section><div class="actions right">${step>0?button('Previous','previous'):''}<button class="primary" type="submit">${step===2?'Finish Setup':'Continue'}</button></div></form></div>`;}
function officeControls(){const o=state.setups.fdtr.office||defaultOffice();return `<details class="office-options"><summary>Office arrangement & consultation target</summary><h3>Office arrangement</h3><label class="check-row"><input id="office-enabled" type="checkbox" ${o.enabled?'checked':''}><span>Account for administrative work in remaining office hours</span></label><p class="hint">Unoccupied working periods are recorded as Others (Adm., R&E). Confirm they reflect work performed. Lunch is excluded; evening teaching is added to the total. Turn this off to enter all work manually.</p><div class="form-grid">${[['start','Office starts'],['end','Office finishes'],['lunchStart','Lunch starts'],['lunchEnd','Lunch finishes']].map(([k,label])=>`<div><label for="office-${k}">${label}</label><input id="office-${k}" data-office="${k}" type="time" value="${o[k]}"></div>`).join('')}<div><label for="office-consultationTarget">Weekly consultation target (hours)</label><input id="office-consultationTarget" data-office="consultationTarget" type="number" min="0" max="40" step="0.5" value="${o.consultationTarget}"><p class="hint">Use your approved faculty arrangement. Default: 10 hours.</p></div></div><fieldset><legend>Office working days</legend><div class="day-options">${[1,2,3,4,5,6,0].map(d=>`<label><input aria-label="${DAYS[d]} office day" data-office-day type="checkbox" value="${d}" ${o.days.includes(d)?'checked':''}>${DAYS[d].slice(0,3)}</label>`).join('')}</div></fieldset></details>`;}
function officeReview(rows){const o=state.setups.fdtr.office||defaultOffice(),added=rows.reduce((sum,r)=>sum+r.sessions.filter(s=>s.generated).reduce((n,s)=>n+duration(s),0),0);return `<details class="panel supporting-review"><summary>Administrative office hours · ${Number(added.toFixed(2))} hours included</summary><p>${o.enabled?`${Number(added.toFixed(2))} hours included as Others (Adm., R&E) in unoccupied working periods.`:'Manual entry is selected. Enter your administrative periods yourself.'}</p><p class="hint">${timeLabel(o.start)}–${timeLabel(o.end)} · Lunch ${timeLabel(o.lunchStart)}–${timeLabel(o.lunchEnd)} · ${o.days.map(d=>DAYS[d].slice(0,3)).join(', ')}. Review Full Month shows each included period. Holidays and explicit daily schedule changes override these periods.</p>${button('Change office arrangement','edit-office','quiet')}</details>`;}
function consultationReview(){const weeks=consultationWeeks(state,month);return `<details class="panel supporting-review"><summary>Weekly consultation review · ${weeks.filter(w=>w.short).length?`${weeks.filter(w=>w.short).length} weeks to check`:"target met"}</summary><p class="hint">Monday–Sunday weeks include dates in adjacent months. The target counts consultation within your office working days and hours, excluding lunch. Compare with your approved arrangement; exceptions may affect the requirement. These checks do not add consultation hours.</p><ul>${weeks.map(w=>`<li>${esc(w.from)} – ${esc(w.to)}: <strong>${Number(w.hours.toFixed(2))} / ${w.target} hours</strong> · ${w.short?'Below target — review':'Target met'}${w.outsideHours>0?` · ${Number(w.outsideHours.toFixed(2))} consultation hours outside the office arrangement — review`:''}${w.exception?' · Schedule exception in this week':''}</li>`).join('')}</ul></details>`;}
function scheduleList(){return `<ul class="schedule-list">${state.setups[type].schedule.map((s,i)=>`<li><div><strong>${s.days.map(d=>DAYS[d].slice(0,3)).join(', ')} · ${CATEGORIES[type][s.category]}</strong><small>${timeLabel(s.start)} – ${timeLabel(s.end)} · ${Number(duration(s).toFixed(2))} hours</small></div><div>${button('Edit','edit-schedule','quiet',`data-index="${i}" aria-label="Edit period ${i+1}"`)}${button('Remove','remove-schedule','quiet',`data-index="${i}" aria-label="Remove period ${i+1}"`)}</div></li>`).join('')||'<li class="empty">No time periods yet.</li>'}</ul>`;}
function monthly(){const rows=buildMonth(state,type,month),s=state.setups[type],record=monthRecord(state,type,month),errors=validateMonth(state,type,month),count=rows.filter(r=>r.sessions.length).length,hours=rows.reduce((sum,r)=>sum+r.total,0);return `${header(`Create ${type.toUpperCase()}`,'Choose your month, add any changes, then review your form.')}<div class="month-layout"><div><section class="panel"><h2>1. Choose the month</h2><label for="month">Month</label><input id="month" type="month" min="1900-01" max="2200-12" value="${month}"><div class="summary"><span><strong>${count}</strong> scheduled days</span><span><strong>${Number(hours.toFixed(2))}</strong> hours</span><span><strong>${Object.keys(record.changes).length}</strong> changed days</span></div></section><section class="panel"><h2>2. Add changes, if needed</h2><p class="muted">${type==='fdtr'?'Add date-specific Related activities here, including half days and full days. These apply only to this month.':'Add a holiday, leave, or a change to your schedule. Otherwise, go straight to preview.'}</p>${button('Add a change','add-change')}<ul class="changes-list">${Object.entries(record.changes).sort((a,b)=>+a[0]-+b[0]).map(([day,c])=>`<li><span><strong>${titleMonth().split(' ')[0]} ${day}</strong> · ${esc(c.kind)}${type==='fdtr'&&c.kind==='Related activity'?`<small>${esc(c.description)} · ${esc(c.scope)}${c.reference?` · ${esc(c.reference)}`:''}</small>`:''}</span><div>${button('Edit','edit-change','quiet',`data-day="${day}" aria-label="Edit change for day ${day}"`)}${button('Remove','remove-change','quiet',`data-day="${day}" aria-label="Remove change for day ${day}"`)}</div></li>`).join('')}</ul></section>${errors.length?`<section class="errors" aria-label="Items to fix"><h3>Before you preview</h3>${errors.slice(0,8).map(e=>`<div class="error-item"><span>${esc(e.text)}</span>${button('Fix','fix','',`data-fix="${e.fix}" data-day="${e.day||''}"`)}</div>`).join('')}${errors.length>8?`<p>And ${errors.length-8} more items to review.</p>`:''}</section>`:''}<div class="next-step"><h2>3. Review & download</h2><p class="hint">Check your names, dates and hours before signing.</p><div class="actions">${button(`Preview ${type.toUpperCase()}`,'preview','primary')}</div></div>${type==='fdtr'?officeReview(rows)+consultationReview():''}<details class="panel" style="margin-top:28px"><summary>Review Full Month</summary><div class="table-scroll" role="region" aria-label="Monthly time entries" tabindex="0"><table class="review"><thead><tr><th scope="col">Day</th><th scope="col">Recorded periods</th><th scope="col">Hours</th><th scope="col">Change</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r.day} ${DAYS[r.weekday].slice(0,3)}</th><td>${r.label?esc(r.label):r.sessions.map(s=>`${CATEGORIES[type][s.category]}${s.generated?' (office arrangement)':''}: ${timeLabel(s.start)} – ${timeLabel(s.end)}`).join('<br>')||'—'}${type==='fdtr'&&r.change?.kind==='Related activity'?`<br><small>${esc(r.change.description)}${r.change.reference?` · ${esc(r.change.reference)}`:''}</small>`:''}</td><td>${r.total?Number(r.total.toFixed(2)):'—'}</td><td>${button('Edit','edit-change','quiet',`data-day="${r.day}" aria-label="Edit day ${r.day}"`)}</td></tr>`).join('')}</tbody></table></div></details><details class="month-tools"><summary>Reset this month</summary><p class="hint">Remove this month’s changes and return to your usual schedule. You can undo this.</p>${button('Start This Month Over','reset','quiet')}</details></div><aside class="aside-note"><span class="tag">USING YOUR SAVED SETUP</span><h3 style="margin-top:18px">${esc(state.profile.name)}</h3><p>${esc(s.term||'Your usual schedule')}<br>${s.schedule.length} recurring time periods</p>${button('Edit saved setup','edit-setup','quiet')}<hr class="divider"><p>Holidays are not guessed. Add the dates that apply to your institution.</p><p class="hint">Review the form before signing. Scheduled hours should reflect the work actually performed.</p></aside></div>`;}
function settings(){return `${button('‹ Back','home','quiet back')}<h1>Settings</h1><p class="muted">Your saved information and a backup for safekeeping.</p><div class="panel narrow">${['dtr','fdtr'].map(t=>`<div class="settings-section"><div><h3>${t.toUpperCase()} setup</h3><p class="hint">${state.setups[t].ready?'Information, schedule and signatory':'Not set up yet'}</p></div>${button('Edit','settings-edit','',`data-type="${t}"`)}</div>`).join('')}<div style="padding-top:25px"><h2>Keep a backup</h2><p class="muted">Your information is saved in this browser. Save a backup before clearing browser data or moving to another device.</p><div class="actions">${button('Save Backup','backup','primary')}${button('Restore Backup','restore')}</div>${protectSave?`<p class="hint">An unreadable save is protected. Download it before replacing it.</p>${button('Download existing save','raw-backup')}${button('Replace unreadable save','replace-corrupt','danger')}`:''}</div></div>`;}
function preview(){return `${button('‹ Back to month','month','quiet back')}<h1>Preview ${type.toUpperCase()}</h1><p class="muted">${titleMonth()} · ${PAPER.label} · ${type==='dtr'?'Two copies on one page':'Two pages'}</p><div class="preview-check"><p id="download-help" class="hint">Review the form below. When it is correct, check this box to enable downloads.</p><label class="check-row"><input type="checkbox" id="reviewed" aria-describedby="download-help" disabled><span>I have checked the dates, time entries, totals, and names. This form reflects the work performed.</span></label></div><div class="preview-toolbar">${button('Download PDF<span class="download-label">For printing · F4 / long bond</span>','pdf','primary','disabled')}${button('Download Word<span class="download-label">For editing in Microsoft Word</span>','word','','disabled')}${button('Fit to screen','fit','quiet')}${button('Actual size','actual','quiet')}</div><div id="preview-status" role="status"></div><p class="hint preview-guidance">Use Fit to screen to see the whole page, or Actual size for a closer look. Check every page before downloading.</p><div class="preview-stage" role="region" aria-label="Form preview" tabindex="0"><div class="preview-scale"><div id="document-preview"><div class="loading">Preparing your institutional form…</div></div></div></div>`;}
async function loadPreview(){const request=previewRequest;try{const blob=await generateDocx(state,type,month);if(view!=='preview'||request!==previewRequest)return;previewBlob=blob;const container=document.querySelector('#document-preview');await renderDocument(previewBlob,container);if(view!=='preview'||request!==previewRequest)return;const pages=container.querySelectorAll('section.institutional');if(pages.length!==(type==='dtr'?1:2))throw Error('The form does not fit its expected pages. Review the length of your names and schedule entries.');document.querySelector('#reviewed').disabled=false;fitPreview();}catch(e){if(request!==previewRequest)return;previewBlob=null;const el=document.querySelector('#preview-status');if(el)el.innerHTML=`<div class="errors" role="alert">${esc(e.message?.startsWith('The form')?e.message:'We could not prepare the preview. Reload this page and try again. Your saved information is still available.')} ${button('Fix saved information','edit-setup')}</div>`;}}
function fitPreview(actual=false){const stage=document.querySelector('.preview-stage'),scale=document.querySelector('.preview-scale');if(!stage||!scale)return;const factor=actual?1:Math.min(1,(stage.clientWidth-48)/CSS_PAPER.width);scale.style.transform=`scale(${factor})`;scale.style.marginBottom=`-${scale.offsetHeight*(1-factor)}px`;}
function openDialog(title,html){const wasOpen=dialog.open,focusedId=wasOpen?document.activeElement?.id:null;if(!wasOpen)dialogOpener=document.activeElement;document.querySelector('#dialog-content').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2>${button('×','close-dialog','icon-button','aria-label="Close dialog"')}</div>${html}`;if(!wasOpen)dialog.showModal();const field=focusedId&&dialog.querySelector(`#${CSS.escape(focusedId)}`);(field||dialog.querySelector('form input:not([type="hidden"]), form select')||dialog.querySelector('button'))?.focus({preventScroll:true});}
dialog.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const controls=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],summary,[tabindex="0"]')].filter(n=>n.getClientRects().length&&getComputedStyle(n).visibility!=='hidden');const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}});
dialog.addEventListener('close',()=>{changeDraft=null;const target=dialogOpener?.isConnected?dialogOpener:main;target.focus({preventScroll:true});dialogOpener=null;});
function timeControls(id,value='08:00'){const [hh,mm]=value.split(':').map(Number);return `<div class="time-controls" data-time="${id}"><select aria-label="${id.startsWith('start')?'Start':'End'} hour, period ${+id.split('-')[1]+1}">${Array.from({length:12},(_,i)=>i+1).map(h=>`<option ${h===(hh%12||12)?'selected':''}>${h}</option>`).join('')}</select><select aria-label="${id.startsWith('start')?'Start':'End'} minute, period ${+id.split('-')[1]+1}">${Array.from({length:60},(_,i)=>`<option ${i===mm?'selected':''}>${String(i).padStart(2,'0')}</option>`).join('')}</select><select aria-label="${id.startsWith('start')?'Start':'End'} AM or PM, period ${+id.split('-')[1]+1}"><option ${hh<12?'selected':''}>AM</option><option ${hh>=12?'selected':''}>PM</option></select></div>`;}
function readTime(id){const values=[...dialog.querySelector(`[data-time="${id}"]`).querySelectorAll('select')].map(n=>n.value);return `${String(+values[0]%12+(values[2]==='PM'?12:0)).padStart(2,'0')}:${values[1]}`;}
function periodHTML(s,index=0){return `<div class="period" data-period="${index}"><div class="period-head"><label>Activity<select data-category aria-label="Activity, period ${index+1}">${Object.entries(CATEGORIES[type]).filter(([k])=>type!=='fdtr'||(changeDraft?.kind==='Related activity'?k==='related':!!changeDraft||k!=='related'||state.setups.fdtr.schedule[scheduleIndex]?.category==='related')).map(([k,v])=>`<option value="${k}" ${s.category===k?'selected':''}>${v}</option>`).join('')}</select></label>${changeDraft?button('Remove','remove-period','quiet',`data-index="${index}" aria-label="Remove period ${index+1}"`):''}</div><div class="time-range"><div><span class="time-label">Start time</span>${timeControls(`start-${index}`,s.start)}</div><div><span class="time-label">End time</span>${timeControls(`end-${index}`,s.end)}</div></div></div>`;}
function readPeriods(){return [...dialog.querySelectorAll('[data-period]')].map(n=>{const i=n.dataset.period;return {category:n.querySelector('[data-category]').value,start:readTime(`start-${i}`),end:readTime(`end-${i}`)};});}
function openSchedule(index=null){changeDraft=null;scheduleIndex=index;const s=index===null?{days:[1],category:Object.keys(CATEGORIES[type])[0],start:'08:00',end:'09:00'}:state.setups[type].schedule[index];openDialog(index===null?'Add a time period':'Edit time period',`<form id="schedule-form"><fieldset style="border:0;padding:0;margin:0"><legend style="font-weight:600;margin-bottom:12px">Repeats on</legend><div class="day-options">${[1,2,3,4,5,6,0].map(d=>`<label><input aria-label="${DAYS[d]}" type="checkbox" name="weekday" value="${d}" ${s.days.includes(d)?'checked':''}>${DAYS[d].slice(0,3)}</label>`).join('')}</div></fieldset>${periodHTML(s)}<div id="dialog-error" role="alert"></div><div class="actions right"><button type="submit" class="primary">Use this period</button></div></form>`);}
function openChange(day=null){scheduleIndex=null;const c=day?monthRecord(state,type,month).changes[day]:null;const officeEdit=type==='fdtr'&&day&&!c;changeDraft={from:day||1,to:day||1,kind:c?.kind||(officeEdit?'Changed Schedule':'Holiday'),label:c?.label??'HOLIDAY',blank:!!c?.blank,scope:c?.scope||'full',description:c?.description||'',reference:c?.reference||'',sessions:structuredClone(c?.sessions||(officeEdit?buildMonth(state,type,month)[day-1].sessions.map(({category,start,end})=>({category,start,end})):[]))};renderChange();}
function activityPreset(){const c=changeDraft;if(c.scope==='custom')return;c.sessions=(c.scope==='morning'?[['08:00','12:00']]:c.scope==='afternoon'?[['13:00','17:00']]:[['08:00','12:00'],['13:00','17:00']]).map(([start,end])=>({category:'related',start,end}));}
function syncChange(){if(!changeDraft)return;changeDraft.from=+dialog.querySelector('#change-from').value;changeDraft.to=+dialog.querySelector('#change-to').value;const label=dialog.querySelector('#change-label');if(label)changeDraft.label=label.value;changeDraft.blank=!!dialog.querySelector('#blank-day')?.checked;changeDraft.sessions=readPeriods();for(const k of ['scope','description','reference']){const el=dialog.querySelector(`#activity-${k}`);if(el)changeDraft[k]=el.value;}}
function renderChange(){const c=changeDraft,related=type==='fdtr'&&c.kind==='Related activity',scheduled=related||['Changed Schedule','Additional Schedule'].includes(c.kind);if(scheduled&&!related&&!c.sessions.length)c.sessions=[{category:related?'related':Object.keys(CATEGORIES[type])[0],start:'08:00',end:'09:00'}];const days=selected=>Array.from({length:daysInMonth(month)},(_,i)=>`<option value="${i+1}" ${i+1===selected?'selected':''}>${i+1}</option>`).join('');openDialog('What was different?',`<form id="change-form"><p class="hint">${titleMonth()}. Choose one day or a range.</p><div class="form-grid"><div><label for="change-from">From day</label><select id="change-from">${days(c.from)}</select></div><div><label for="change-to">Through day</label><select id="change-to">${days(c.to)}</select></div><div class="full"><label for="change-kind">Change</label><select id="change-kind">${['Holiday','Leave','No Class',...(type==='fdtr'?['Related activity']:[]),'Changed Schedule','Additional Schedule','Other'].map(k=>`<option ${c.kind===k?'selected':''}>${k}</option>`).join('')}</select></div></div>${related?`<div class="form-grid" style="margin-top:20px"><div><label for="activity-description">Activity description (printed)</label><input id="activity-description" maxlength="60" required value="${esc(c.description)}" placeholder="e.g. Research Week"></div><div><label for="activity-reference">Memo / special order reference (optional)</label><input id="activity-reference" maxlength="100" value="${esc(c.reference)}"></div><div><label for="activity-scope">Part of day affected</label><select id="activity-scope">${Object.entries({full:'Full day',morning:'Morning only',afternoon:'Afternoon / evening only',custom:'Only the entered time periods'}).map(([v,label])=>`<option value="${v}" ${c.scope===v?'selected':''}>${label}</option>`).join('')}</select></div></div><p class="hint">Adjust the times to match the order. Full day replaces all usual periods; morning ends at noon; afternoon starts at noon. Custom times replace only overlapping work. Breaks are excluded from hours. The reference stays in your monthly record and backup.</p>`:''}${scheduled?`<p class="hint">${related?'These hours are recorded under Related activities. Work outside the selected part of the day is retained.':c.kind==='Changed Schedule'?'These periods replace the entire day’s saved schedule.':'These periods are added to the usual schedule.'}</p><div>${c.sessions.map(periodHTML).join('')}</div>${button('Add another period','add-period')}`:`<div style="margin-top:20px"><label for="change-label">Wording to print on the form</label><input id="change-label" maxlength="36" value="${esc(c.label)}" ${c.blank?'disabled':'required'}><label class="check-row" style="margin-top:12px"><input type="checkbox" id="blank-day" ${c.blank?'checked':''}><span>Leave the day’s time entries blank, with no printed label</span></label><p class="hint">${c.kind==='Holiday'?'The supplied forms use HOLIDAY.':'Enter the wording your institution requires; the reference does not establish a label for this change.'} This change clears all time entries on the selected days.</p></div>`}<div id="dialog-error" role="alert"></div><div class="actions right"><button class="primary" type="submit">Apply change</button></div></form>`);}
function error(target,messages){document.querySelector(target).innerHTML=`<div class="errors" tabindex="-1" style="margin-top:18px"><strong>Please check:</strong><ul>${messages.map(m=>`<li>${esc(m)}</li>`).join('')}</ul></div>`;document.querySelector(target).firstElementChild.focus();}
function checkpoint(){undo=structuredClone(state);}
function persistChange(day,c){state.months[type][month]??={changes:{}};state.months[type][month].changes[day]=c;}
async function handleAction(action,el){const index=Number(el.dataset.index),day=Number(el.dataset.day);switch(action){case'dismiss-toast':document.querySelector('#toast').classList.remove('visible');main.focus({preventScroll:true});break;case'home':show('home');break;case'settings':show('settings');break;case'choose':type=el.dataset.type;if(state.setups[type].ready)show('month');else{step=0;show('setup');}break;case'settings-edit':type=el.dataset.type;step=0;show('setup');break;case'edit-setup':step=0;show('setup');break;case'edit-office':step=1;show('setup');main.querySelector('.office-options').open=true;break;case'previous':step--;render();break;case'back-setup':show(state.setups[type].ready?'month':'home');break;case'add-schedule':openSchedule();break;case'edit-schedule':openSchedule(index);break;case'remove-schedule':checkpoint();state.setups[type].schedule.splice(index,1);save();render();toast('Time period removed.',true);break;case'close-dialog':dialog.close();changeDraft=null;break;case'add-change':openChange();break;case'edit-change':openChange(day);break;case'remove-change':checkpoint();delete state.months[type][month].changes[day];save();render();toast('Change removed. Your usual schedule applies again.',true);break;case'add-period':syncChange();changeDraft.sessions.push({category:type==='fdtr'&&changeDraft.kind==='Related activity'?'related':Object.keys(CATEGORIES[type])[0],start:'08:00',end:'09:00'});renderChange();break;case'remove-period':syncChange();changeDraft.sessions.splice(index,1);renderChange();break;case'fix':if(el.dataset.fix==='day')openChange(day);else{step={info:0,schedule:1,signatory:2}[el.dataset.fix];show('setup');}break;case'preview':if(validateMonth(state,type,month).length){toast('Please fix the listed items before previewing.');main.querySelector('.errors')?.scrollIntoView({behavior:'smooth'});}else show('preview');break;case'month':show('month');break;case'fit':fitPreview();break;case'actual':fitPreview(true);break;case'word':if(previewBlob&&document.querySelector('#reviewed').checked)download(previewBlob,`${type.toUpperCase()}-${month}.docx`);break;case'pdf':if(!previewBlob||!document.querySelector('#reviewed').checked)return;el.disabled=true;el.textContent='Preparing PDF…';try{download(await makePDF(document.querySelector('#document-preview')),`${type.toUpperCase()}-${month}.pdf`);}catch{toast('We could not create the PDF. Reopen the preview and try again.');}finally{el.disabled=false;el.innerHTML='Download PDF<span class="download-label">For printing · F4 / long bond</span>';}break;case'reset':if(!Object.keys(monthRecord(state,type,month).changes).length){toast('This month already uses your usual schedule.');break;}openDialog('Start this month over?',`<p>Remove all changes for ${titleMonth()} in ${type.toUpperCase()}? Your saved information and usual schedule will stay.</p><div class="actions right">${button('Keep my changes','close-dialog')}${button('Start This Month Over','confirm-reset','danger')}</div>`);break;case'confirm-reset':checkpoint();delete state.months[type][month];save();dialog.close();render();toast('This month now uses your usual schedule.',true);break;case'undo':if(undo){state=undo;undo=null;save();render();toast('Previous information restored.');}break;case'backup':download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),`DTR-FDTR-${new Date().toISOString().slice(0,10)}.dtrbackup`);toast('Backup downloaded. Keep it somewhere safe.');break;case'restore':document.querySelector('#backup-input').click();break;case'confirm-restore':checkpoint();state=restoreCandidate;restoreCandidate=null;protectSave=false;save();dialog.close();show('settings');toast('Backup restored.',true);break;case'raw-backup':download(new Blob([localStorage.getItem(KEY)||''],{type:'application/json'}),'DTR-FDTR-recovery.dtrbackup');break;case'replace-corrupt':openDialog('Replace the unreadable save?',`<p>Save a recovery copy first if you may need the old information. This replaces the browser’s unreadable save with your current information.</p><div class="actions">${button('Cancel','close-dialog')}${button('Replace saved information','confirm-corrupt','danger')}</div>`);break;case'confirm-corrupt':protectSave=false;save();dialog.close();render();break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();Promise.resolve(handleAction(el.dataset.action,el)).catch(()=>toast('That action could not be completed. Please try again.'));}});
document.addEventListener('input',e=>{const office=e.target.dataset.office;if(office&&type==='fdtr'){state.setups.fdtr.office??=defaultOffice();state.setups.fdtr.office[office]=office==='consultationTarget'?+e.target.value:e.target.value;save();}const field=e.target.dataset.field;if(field){const [group,key]=field.split('.');(group==='profile'?state.profile:state.setups[type])[key]=e.target.value;save();}});
document.addEventListener('change',e=>{if(type==='fdtr'&&(e.target.id==='office-enabled'||e.target.hasAttribute('data-office-day'))){state.setups.fdtr.office??=defaultOffice();const o=state.setups.fdtr.office;if(e.target.id==='office-enabled')o.enabled=e.target.checked;else o.days=[...main.querySelectorAll('[data-office-day]:checked')].map(n=>+n.value);save();}if(e.target.id==='month'){try{daysInMonth(e.target.value);month=e.target.value;render();}catch{toast('Choose a valid month and year.');}}if(e.target.id==='reviewed'){for(const b of document.querySelectorAll('[data-action="word"],[data-action="pdf"]'))b.disabled=!e.target.checked||!previewBlob;}if(e.target.id==='blank-day'){dialog.querySelector('#change-label').disabled=e.target.checked;dialog.querySelector('#change-label').required=!e.target.checked;}if(e.target.id==='activity-scope'){syncChange();activityPreset();renderChange();}if(e.target.id==='change-kind'){syncChange();changeDraft.kind=e.target.value;changeDraft.label=changeDraft.kind==='Holiday'?'HOLIDAY':'';if(type==='fdtr'&&changeDraft.kind==='Related activity')activityPreset();renderChange();}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='setup-form'){if(step===1){const s=state.setups[type],errors=[];if(type==='fdtr')errors.push(...validateOffice(s.office||defaultOffice()));if(!s.schedule.length)errors.push('Add at least one usual time period.');if(s.from&&s.to&&s.from>s.to)errors.push('The end date must be on or after the start date.');for(let d=0;d<7;d++)for(const msg of validateSessions(s.schedule.filter(p=>p.days.includes(d)),type))errors.push(`${DAYS[d]}: ${msg}`);if(errors.length){error('#setup-error',errors);return;}}if(step<2){step++;render();}else{state.setups[type].ready=true;save();show('month');}}if(e.target.id==='schedule-form'){const session={...readPeriods()[0],days:[...dialog.querySelectorAll('[name="weekday"]:checked')].map(n=>+n.value)},errors=validateSessions([session],type);if(!session.days.length)errors.push('Choose at least one day.');const others=state.setups[type].schedule.filter((_,i)=>i!==scheduleIndex);for(const d of session.days)for(const msg of validateSessions([...others.filter(s=>s.days.includes(d)),session],type))errors.push(`${DAYS[d]}: ${msg}`);if(errors.length){error('#dialog-error',[...new Set(errors)]);return;}if(scheduleIndex===null)state.setups[type].schedule.push(session);else state.setups[type].schedule[scheduleIndex]=session;save();dialog.close();render();}if(e.target.id==='change-form'){syncChange();const c=changeDraft;const errors=[];if(c.to<c.from)errors.push('The last day must be on or after the first day.');const related=type==='fdtr'&&c.kind==='Related activity',scheduled=related||['Changed Schedule','Additional Schedule'].includes(c.kind);if(related)errors.push(...validateRelatedActivity(c));if(scheduled)errors.push(...validateSessions(c.sessions,type));else if(!c.blank&&!c.label.trim())errors.push('Enter the wording to print on the form.');const candidate=structuredClone(state);candidate.months[type][month]??={changes:{}};for(let d=c.from;d<=c.to;d++)candidate.months[type][month].changes[d]={...(related?{scope:c.scope,description:c.description.trim(),reference:c.reference.trim()}:{}),kind:c.kind,label:scheduled||c.blank?'':c.label.trim(),...(!scheduled&&c.blank?{blank:true}:{}),sessions:scheduled?c.sessions:[]};for(const r of buildMonth(candidate,type,month).filter(r=>r.day>=c.from&&r.day<=c.to)){for(const msg of validateSessions(r.sessions,type))errors.push(`Day ${r.day}: ${msg}`);if(related&&['class','consultation'].some(cat=>r.sessions.filter(s=>s.category===cat).length===3))errors.push(`Day ${r.day}: leave a row free in Class and Consultation for the activity description.`);}if(errors.length){error('#dialog-error',[...new Set(errors)]);return;}checkpoint();state=candidate;save();dialog.close();changeDraft=null;render();toast('Monthly change applied.',true);}});
document.querySelector('#backup-input').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>2_000_000)throw Error('This backup is too large. Choose a backup made by this app.');restoreCandidate=validateBackup(JSON.parse(await file.text()));openDialog('Restore this backup?',`<p>This backup is for <strong>${esc(restoreCandidate.profile.name||'an unnamed faculty member')}</strong>.</p><p>It contains ${restoreCandidate.setups.dtr.schedule.length} DTR and ${restoreCandidate.setups.fdtr.schedule.length} FDTR time periods. Restoring replaces your current saved information on this device.</p><div class="actions right">${button('Cancel','close-dialog')}${button('Restore Backup','confirm-restore','primary')}</div>`);}catch(err){toast(err instanceof SyntaxError?'This file could not be read as an app backup.':err.message);}});
window.addEventListener('resize',()=>{if(view==='preview')fitPreview();});render();
